 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]

    # Repeated horizontal bars touching the top or bottom edge are ray sources.
    bars = []
    for r in (0, h - 1):
        c = 0
        while c < w:
            color = grid[r][c]
            end = c + 1
            while end < w and grid[r][end] == color:
                end += 1
            if color != bg and end - c >= 2:
                bars.append((r, c, end, color))
            c = end

    if not bars:
        return out

    source_colors = {b[3] for b in bars}
    # Isolated non-background pixels are the ray color / stopping markers.
    singles = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or color in source_colors:
                continue
            neighbors = 0
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    neighbors += 1
            if neighbors == 0:
                singles.append((r, c, color))
    ray_color = singles[0][2] if singles else next((v for v in counts if v != bg and v not in source_colors), bg)

    # Rays run inward from each bar; markers become color 4 and stop the ray.
    for r, left, right, _ in bars:
        step = 1 if r == 0 else -1
        for c in range(left, right):
            rr = r + step
            while 0 <= rr < h:
                if grid[rr][c] == ray_color:
                    out[rr][c] = 4
                    break
                if grid[rr][c] != bg:
                    break
                out[rr][c] = ray_color
                rr += step
    return out
