    paint=markers[0][2]
    # Markers are at successive slope positions; the bars define the width.
    # Fill the two bar-spanned areas all the way across, with marker cells gray.
    top=next(b for b in bars if b[0]==0); bottom=next(b for b in bars if b[0]==h-1)
