 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Find contiguous edge runs of a color distinct from the background.
    bars = []
    for r in (0, h - 1):
        c = 0
        while c < w:
            color = grid[r][c]
            e = c + 1
            while e < w and grid[r][e] == color:
                e += 1
            if color != bg and e - c >= 2:
                bars.append((r, c, e, color))
            c = e
    if not bars:
        return out
    bar_colors = {b[3] for b in bars}

    # Remaining non-background cells are marker pixels.
    markers = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or color in bar_colors:
                continue
            markers.append((r, c, color))
    if not markers:
        return out
    marker_color = markers[0][2]

    # From each marker, fill a horizontal band toward the nearest bar-side
    # direction (the demo shows rays perpendicular to the long border bars).
    for r, c, _ in markers:
        out[r][c] = 4
        # Fill horizontally from marker toward the nearest edge bar segment.
        candidates = [b for b in bars if b[0] in (0, h - 1)]
        for cc in range(c + 1, w):
            if grid[r][cc] == bg:
                out[r][cc] = marker_color
            elif grid[r][cc] != marker_color:
                break
        for cc in range(c - 1, -1, -1):
            if grid[r][cc] == bg:
                out[r][cc] = marker_color
            elif grid[r][cc] != marker_color:
                break

    # Long boundary bars project across their full interior span; marker
    # color fills only from the bar up to the marker line.
    for r, left, right, _ in bars:
        if r == 0:
            step = 1
        else:
            step = -1
        for c in range(left, right):
            rr = r + step
            while 0 <= rr < h:
                if grid[rr][c] == marker_color:
                    out[rr][c] = 4
                    break
                if grid[rr][c] != bg:
                    break
                out[rr][c] = marker_color
                rr += step
    return out
